cat <<'EOF' > /app/_run_tests.py
"""Minimal pytest-compatible shim to run our tests without pytest installed.

Supports: pytest.raises, tmp_path fixture, capsys fixture.
Only for local verification; the real suite runs under pytest.
"""
import io
import sys
import types
import tempfile
import pathlib
import traceback
import contextlib
import importlib


class _Raises:
    def __init__(self, exc):
        self.exc = exc
        self.value = None
    def __enter__(self):
        return self
    def __exit__(self, et, ev, tb):
        assert et is not None, f"DID NOT RAISE {self.exc}"
        assert issubclass(et, self.exc), f"raised {et} not {self.exc}"
        self.value = ev
        return True


class _Capsys:
    def __init__(self, out, err):
        self._out = out
        self._err = err
    def readouterr(self):
        o = self._out.getvalue()
        e = self._err.getvalue()
        return types.SimpleNamespace(out=o, err=e)


# fake pytest module
pytest = types.ModuleType("pytest")
pytest.raises = lambda exc: _Raises(exc)
sys.modules["pytest"] = pytest

test_modules = ["tests.test_animals", "tests.test_ecosystem", "tests.test_statistics"]
passed = failed = 0
failures = []
for modname in test_modules:
    mod = importlib.import_module(modname)
    for name in sorted(dir(mod)):
        if not name.startswith("test_"):
            continue
        fn = getattr(mod, name)
        if not callable(fn):
            continue
        params = fn.__code__.co_varnames[: fn.__code__.co_argcount]
        kwargs = {}
        tmpdir = None
        out = io.StringIO(); err = io.StringIO()
        if "tmp_path" in params:
            tmpdir = tempfile.TemporaryDirectory()
            kwargs["tmp_path"] = pathlib.Path(tmpdir.name)
        if "capsys" in params:
            kwargs["capsys"] = _Capsys(out, err)
        try:
            if "capsys" in params:
                with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
                    fn(**kwargs)
            else:
                fn(**kwargs)
            passed += 1
        except Exception:
            failed += 1
            failures.append((modname, name, traceback.format_exc()))
        finally:
            if tmpdir:
                tmpdir.cleanup()

print(f"\nPASSED: {passed}  FAILED: {failed}")
for m, n, tb in failures:
    print(f"\n--- FAIL {m}::{n} ---\n{tb}")
sys.exit(1 if failed else 0)
EOF
cd /app && python _run_tests.py

